def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows and columns are the full-width/full-height uniform lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    sep = grid[sep_rows[0]][0] if sep_rows else (grid[0][sep_cols[0]] if sep_cols else 5)

    row_starts = [0] + [r + 1 for r in sep_rows]
    col_starts = [0] + [c + 1 for c in sep_cols]
    row_starts = [r for r in row_starts if r < h]
    col_starts = [c for c in col_starts if c < w]

    # Extract the distinctive object from any panel other than the first column.
    shape = None
    for br in row_starts:
        for bc in col_starts[1:]:
            pts = [(r, c) for r in range(br, min(br + 4, h))
                   for c in range(bc, min(bc + 4, w))
                   if grid[r][c] != 0 and grid[r][c] != sep]
            if pts:
                shape = [(r - br, c - bc) for r, c in pts]
                break
        if shape:
            break
    if not shape:
        return grid

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = [sep] * w
    for c in sep_cols:
        for r in range(h):
            out[r][c] = sep

    for br in row_starts:
        # Color of the seed object in the leftmost panel of this row band.
        color = next((grid[r][c] for r in range(br, min(br + 4, h))
                      for c in range(0, min(4, w))
                      if grid[r][c] not in (0, sep)), 0)
        if color == 0:
            continue
        for bc in col_starts:
            for dr, dc in shape:
                if br + dr < h and bc + dc < w:
                    out[br + dr][bc + dc] = color
    return out
